/// Asset-bundle [GeoResourceLoader] for offline-first hosts (P1-05).
///
/// Reads resources the host declared under a configurable asset prefix, e.g.
/// the entries generated by the P1-06 assets CLI. Runs fully offline; a
/// missing asset surfaces as [GeoNotFoundError] so the repository can fall
/// through to a remote source when one is configured.
///
/// No `dart:io`: asset loading goes through `package:flutter/services.dart`,
/// keeping Web compatibility (PRD GR-12 / PLAN P1-05 gate).
library;

import 'dart:typed_data';

import 'package:flutter/foundation.dart' show FlutterError;
import 'package:flutter/services.dart' show AssetBundle, ByteData, rootBundle;

import '../errors.dart';
import 'contracts.dart';

/// Loads manifest-relative resource paths from Flutter asset bundles.
///
/// The loader receives dataset-root-relative URIs (for example
/// `regions/JP.json`) and reads `assetPrefix + path` from [bundle]; hosts
/// usually keep the default `assets/geo_regions/` prefix that matches the
/// assets CLI output.
class GeoAssetBundleLoader implements GeoResourceLoader {
  /// Creates a loader; [bundle] defaults to [rootBundle] and is injectable
  /// for deterministic tests.
  GeoAssetBundleLoader({
    AssetBundle? bundle,
    this.assetPrefix = 'assets/geo_regions/',
  }) : bundle = bundle ?? rootBundle;

  /// Bundle the assets are read from.
  final AssetBundle bundle;

  /// Prefix prepended to every manifest-relative path.
  final String assetPrefix;

  @override
  Future<GeoBytes> load(Uri resourceUri) async {
    final relative = _relativePath(resourceUri);
    final assetKey = '$assetPrefix$relative';
    final ByteData data;
    try {
      data = await bundle.load(assetKey);
    } on FlutterError catch (error) {
      throw GeoNotFoundError(
        'bundled geo asset not found: $assetKey (${error.message})',
      );
    }
    final bytes = data.buffer.asUint8List(
      data.offsetInBytes,
      data.lengthInBytes,
    );
    return GeoBytes(Uint8List.fromList(bytes), contentLength: bytes.length);
  }

  String _relativePath(Uri uri) {
    var path = uri.path;
    while (path.startsWith('/')) {
      path = path.substring(1);
    }
    if (path.isEmpty || path.contains('..')) {
      throw GeoNotFoundError('unsafe bundled geo asset path: $uri');
    }
    return path;
  }
}
